@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
}

class ScheduledPickup {
  + StreetAddress : string
  + Description : string
  + PickupTime : time
}

class Item {
  + Description : string
  + Dimensions : string
  + Weight : float
}

class Article {
  + Description : string
  + RFID : string
}

class Category {
  + Name : string
}

class Vehicle {
  + StorageSpace : float
}

class Route {
  + Date : date
}

class VolunteerDriver {
  + Name : string
}

class H2SLocation {
}

class H2SEmployee {
  + Name : string
}

class Client {
  + HomeAddress : string
  + NeededCategories : string[]
}

class FoodBank {
}

Resident "1" -- "*" ScheduledPickup : schedules
ScheduledPickup "1" -- "1" Resident : at
ScheduledPickup "1" -- "*" Item : includes
Item "1" -- "0..1" Article : becomes
Article "*" -- "1" Category : belongs to
Vehicle "1" -- "*" Route : assigned to
Route "1" -- "*" ScheduledPickup : contains
VolunteerDriver "*" -- "*" Route : drives
VolunteerDriver "1" -- "*" Route : operates
H2SLocation "1" -- "*" Vehicle : operates
H2SLocation "1" -- "*" H2SEmployee : employs
H2SLocation "1" -- "1" DistributionCenter
DistributionCenter "1" -- "*" H2SEmployee : works at
DistributionCenter "1" -- "*" Article : examines
Client "1" -- "1" H2SLocation : located in
Client "1" -- "*" Article : receives
Client "1" -- "1" Resident : is a
VolunteerDriver "1" -- "*" Article : delivers
FoodBank "1" -- "*" Item : receives

class DistributionCenter {}

@enduml

